<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRouter} from 'vue-router';import {ArrowRight} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createRun} from '../api/runs';import LibrarySelector from '../components/LibrarySelector.vue';import Notice from '../components/common/Notice.vue';const s=useResearchData(),auth=useAuth(),a=useAction(),router=useRouter(),selected=ref(0),chosen=ref<number[]>([]),name=ref(''),sigma=ref(.005),repeats=ref(80),seed=ref(2026),noiseMode=ref<'blank'|'legacy'>('blank'),calibrationId=ref(0);const library=computed(()=>s.libraries.find(l=>l.id===selected.value)||s.libraries[0]);const libraryCalibrations=computed(()=>s.calibrations.filter(c=>c.library_id===library.value?.id));const currentCalibrations=computed(()=>libraryCalibrations.value.filter(c=>c.rule_current));const chosenCalibration=computed(()=>currentCalibrations.value.find(c=>c.id===calibrationId.value));const staleCalibrations=computed(()=>libraryCalibrations.value.filter(c=>!c.rule_current));watch(()=>library.value?.id,async id=>{if(id){await Promise.all([s.loadLibrary(id),s.loadCalibrations(id)]);chosen.value=s.samples.slice(0,3).map(x=>x.id);calibrationId.value=currentCalibrations.value[0]?.id||0;noiseMode.value=currentCalibrations.value.length?'blank':'legacy'}},{immediate:true});function submit(){a.execute(async()=>{const payload=noiseMode.value==='blank'?{name:name.value,library_id:library.value.id,sample_ids:chosen.value,noise_mode:'blank' as const,calibration_id:calibrationId.value,noise_sigma:null,repeats:repeats.value,seed:seed.value}:{name:name.value,library_id:library.value.id,sample_ids:chosen.value,noise_mode:'legacy' as const,noise_sigma:sigma.value,calibration_id:null,repeats:repeats.value,seed:seed.value};const run=await createRun(payload);router.push('/results?run='+run.id)})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">UNMIXING PROTOCOL / 03</p><h1>解混配置<span>非负、和为一，与固定端元假设一起生效。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><div class="editor-grid"><form @submit.prevent="submit"><label>研究名称<input aria-label="研究名称" v-model="name" minlength="2" maxlength="120" required placeholder="例如：首批矿物三样本复配研究" :disabled="auth.user?.role==='viewer'"/></label><LibrarySelector :libraries="s.libraries" :model-value="library?.id||0" @update:model-value="selected=$event"/><div v-if="library&&!library.supported" class="notice">{{library.reason}}</div><div class="form-heading"><span>01</span><h2>选择混合样本</h2></div><div class="sample-selector"><label v-for="sample in s.samples" :key="sample.id"><input type="checkbox" :value="sample.id" v-model="chosen"/><span>{{sample.code}}<small>{{sample.name}}</small></span></label></div><p class="caption">已选{{chosen.length}}个；允许1–6个，样本数×重复数≤480。</p><div class="form-heading"><span>02</span><h2>条件测量噪声</h2></div><div class="noise-mode"><label><input type="radio" value="blank" v-model="noiseMode" :disabled="!currentCalibrations.length"/>空白联合噪声</label><label><input type="radio" value="legacy" v-model="noiseMode"/>旧版独立等方差噪声</label></div><label v-if="noiseMode==='blank'">空白校准<select aria-label="空白校准" v-model.number="calibrationId"><option v-for="c in currentCalibrations" :key="c.id" :value="c.id">#{{c.id}} / {{c.name}} · 有效测量数 {{c.effective_measurements}}</option><option v-if="!currentCalibrations.length" :value="0">该库尚无当前规则校准，请先建立空白校准</option></select></label><div v-if="noiseMode==='blank'&&chosenCalibration" class="calibration-note"><span>联合协方差来源</span><p>规则 {{chosenCalibration.rule_version}} · 有效测量数 {{chosenCalibration.effective_measurements}} · 自由度 {{chosenCalibration.degrees_of_freedom}} · 噪声RMS {{chosenCalibration.noise_rms.toFixed(5)}} · 条件数 {{chosenCalibration.condition_number.toExponential(2)}}</p><small class="fingerprint">{{chosenCalibration.calibration_hash}}</small></div><div v-if="staleCalibrations.length" class="notice">有{{staleCalibrations.length}}份校准按旧规则估计，新研究不能选用；请到“空白校准”页按当前规则重算。</div><div v-if="noiseMode==='legacy'" class="form-row"><label>已知测量sigma<input aria-label="测量sigma" type="number" min="0" max=".2" step=".001" v-model.number="sigma"/></label></div><label>条件重拟合次数<input aria-label="重拟合次数" type="number" min="20" max="120" v-model.number="repeats"/></label><label>根随机种子<input aria-label="随机种子" type="number" min="0" max="2147483647" v-model.number="seed"/></label><p v-if="noiseMode==='blank'" class="caption">按空白校准的跨波段联合协方差生成扰动，并以广义最小二乘重拟合；分位范围不覆盖端元误差，也不保证真实配比覆盖。</p><p v-else class="caption">以观测谱加独立Gaussian噪声，固定端元重拟合。范围不包括端元误差，也不保证真实配比覆盖；sigma=0时扰动退化。旧版独立噪声不体现相邻波段相关。</p><button v-if="auth.user?.role!=='viewer'" class="primary" :disabled="a.busy.value||!library?.supported||chosen.length<1||chosen.length>6||chosen.length*repeats>480||(noiseMode==='blank'&&!chosenCalibration)">提交解混研究 <ArrowRight :size="16"/></button><p v-else class="role-note">阅读者可查看配置，提交研究需要研究员权限。</p></form><aside class="method-note"><span class="eyebrow">METHOD NOTE / 01</span><h2>先检查，<br/>再枚举支持集。</h2><ol><li><b>增广满列秩</b><p>[A;1]需满列秩，条件数≤1e6。秩亏或病态不输出貌似唯一的配比。</p></li><li><b>约束全局最小RSS</b><p>枚举非空支持集，解等式KKT并筛非负；结果再检查完整KKT。</p></li><li><b>噪声来源要留痕</b><p>空白联合噪声按相关协方差重拟合；独立σ只作旧数据兼容。</p></li></ol></aside></div></div></template>
